		// 1090214 Raymond 1080420 新增更新單一條列內文功能
		this.refreshContent = function() {
			if(!!this.anchor && !!this.anchor.syncPath && this.anchor.syncPath.match(/文字/g)) {
				theLogger.warn("重新整理條列[" + this.anchor.syncPath + "]");
				try {	// 2015.12.29 加try-catch
					var ctx = this.para.getModel().text(this.anchor.syncPath);
					theLogger.debug(this.anchor.syncPath + "='" + ctx + "'");	// 2015.6.26 for debug
					if(ctx.length == 0 && (isMobile || readOnly))	// 2016.10.17 FIX for iPad游標不會顯示的問題, 2016.10.19 只改在iPad, 2017.1.4 fix for 長官不允許編輯時, 空行仍須顯示
						this.$edit.html("&nbsp;");
					else
						this.$edit.html(ctx);
					if("children" in this.anchor)
						this.anchor.children.length = 0;
					
					// 1060829 Raymond 1060805 修正INS內層DEL外層的情況下, tool tip只會顯示內層INS的title問題
					var that = this;
					this.$edit.find("DEL").attr("title", function() {
						var sn = $(this).attr("data-sn");
						var tcSess = that.para.getModel().getTCSess(sn);
						var res = $(this).attr("data-date") + "\r\n刪除：" + tcSess.name;
						if($(this).find("INS").length > 0) {
							res += ("\r\n\r\n" + $(this).find("INS").attr("title"));
							$(this).find("INS").removeAttr("title");	// 移除內層元素的title屬性, 外層的DEL的title屬性才能被顯示
						}
						return res;
					});
				}
				catch(e) {
					theLogger.error(e.stack || e.message);
				}
			}
		}
		
