						theLogger.log(((that.anchor.id)?("#" + that.anchor.id) : ("'" + that.anchor.syncPath + "'")) + ".on" + event.type + " - data:'" + event.originalEvent.data + "'(" + typeof event.originalEvent.data + "), inputMethod:" + event.originalEvent.inputMethod + ", _inputByPaste:" + _inputByPaste + ", _inputByUndo:" + _inputByUndo + ", isTrigger:" + event.isTrigger + ", _duringIME:" + _duringIME + ", _duringIMEFunctionKeydown:" + _duringIMEFunctionKeydown, event.originalEvent);	// 1080920 Raymond 1080830 新增isTrigger, _duringIME, _duringIMEFunctionKeydown, originalEvent等資訊
