		function refreshAnchorContext() {
			if("syncPath" in this.anchor && this.anchor.syncPath.match(/文字/g)) {
				try {	// 2015.12.29 加try-catch
					var ctx = this.para.getModel().text(this.anchor.syncPath);
					theLogger.log(this.anchor.syncPath + "='" + ctx + "'");	// 2015.6.26 for debug
					if(ctx.length == 0 && (isMobile || readOnly))	// 2016.10.17 FIX for iPad游標不會顯示的問題, 2016.10.19 只改在iPad, 2017.1.4 fix for 長官不允許編輯時, 空行仍須顯示
						this.$edit.html("&nbsp;");
					else
						this.$edit.html(ctx);
					if("children" in this.anchor)
						this.anchor.children.length = 0;
					
					// 記憶初始值做為下次onblur時的前次設定值
					//this.prevTx = this.para.getModel().pureText(this.anchor.syncPath);	// 2015.7.17 改用過濾掉act=del的純文字內容做為比對字串
				}
				catch(e) {
					theLogger.error(e.message);
				}
			}
		}
		// 2015.6.25 新增復原刪除功能
		this.undoDel = function(rng) {
			theLogger.log("執行復原刪除");
			theLogger.log([this, rng]);
			var c = this.$para.closest(".viewPort").data("editCursor");
			try {
				// 1060908 Raymond 1060672 rng若是jQuery.Event, 則選取整個段落
				//if(typeof rng === "undefined") {	// 2016.3.14 未定義rng, 則選取整個段落
				if(typeof rng === "undefined" || "originalEvent" in rng) {
					// 1070724 Raymond 1070354 修正在Chrome下完稿模式剪下緊隣DEL節點的文字時, DEL會跟著消失, 導致復原全部刪除會沒有東西可復原的問題
					if(navigator.userAgent.indexOf("Chrome") >= 0) {
						refreshAnchorContext.call(this);
					}
					rng = document.createRange();
					rng.selectNodeContents(this.$edit.get(0));
					//window.getSelection().removeAllRanges();
					//window.getSelection().addRange(rng);
				}
				else {	// 2016.3.15 重抓目前選取範圍
					//rng = window.getSelection().getRangeAt(0);	// 1060908 Raymond 1060672 應該不用這行
				}
				if(navigator.userAgent.indexOf("Trident") >= 0) {	// 1060906 Raymond 1060672 IE在操作DOM時經常自動觸發textinput, 須忽略之
					_inputByUndo = true;
					_selectRangeKeeped = true;	// 1070718 Raymond 修正在IE下刪除部分文字後執行復原全部刪除後, 會有非選取範圍再直接打字所被刪除的文字被記憶, 此時在某位置直接打字會被加上不存在該位置的刪除記錄的問題
				}
				c.undoDel(rng, this.para.getModel());
				if(navigator.userAgent.indexOf("Trident") >= 0) {	// 1060906 Raymond 1060672 IE在操作DOM時經常自動觸發textinput, 忽略之後恢復
					_inputByUndo = false;
					_selectRangeKeeped = false;	// 1070718 Raymond 恢復flag
				}
				this.para.getModel().text(this.anchor.syncPath, this.$edit.get(0));	// 2015.6.26 寫回<文字>
				this.prevTx = this.para.getModel().pureText(this.anchor.syncPath);	// 1070223 Raymond 1061140 復原刪除後重設prevTx
			}
			catch(e) {
				theLogger.error(e.message + " - " + e.sourceURL + ":" + e.line);
			}
			c.cmdFloat.hide();	// 2015.8.5 新增復原後隱藏指令列
		}
