	// 1130116 Raymond 1120887 將標號span的初始化獨立為一個function, 供Plain初始化及判斷分會單位可編輯Anchor時再初始化Plain
	function _doAttachPlain() {
		this.showNumber = this.$span.text().length > 0;	// 2015.12.3 未顯示標號
		
		var that = this;
		var blockSwiping = false;
		var touchStartEvent = $.mobile.support.touch ? "touchstart" : "mousedown",
			touchMoveEvent = $.mobile.support.touch ? "touchmove" : "mousemove",
			touchStopEvent = $.mobile.support.touch ? "touchend" : "mouseup";
		
		this.$span.addClass("numbering")	// 1130116 Raymond 1120887 由於包成一個function給Anchor的初始化叫用, 故$sp要改成this.$span
			.on( touchStartEvent, function(event) {
				var start = {
						time: ( new Date() ).getTime(),
						coords:[event.originalEvent.touches ? event.originalEvent.touches[0].pageX : event.pageX,
								event.originalEvent.touches ? event.originalEvent.touches[0].pageY : event.pageY ],
						origin: $( event.target )},
					stop;
				
				function moveHandler( event ) {
					if ( !start )
						return;
					
					stop = {
						time: ( new Date() ).getTime(),
						coords:[event.originalEvent.touches ? event.originalEvent.touches[0].pageX : event.pageX,
								event.originalEvent.touches ? event.originalEvent.touches[0].pageY : event.pageY ]
					};
					
					// prevent scrolling
					if ( Math.abs( start.coords[ 0 ] - stop.coords[ 0 ] ) > $.event.special.swipe.scrollSupressionThreshold ) {
						event.preventDefault();
					}
				}
				
				var $pg = $(this).closest(".pg");	// 桌面版必須在.pg攔mousemove及mouseup, 通常會劃出span.numbering範圍外導致接不到事件
				$pg.on( touchMoveEvent, moveHandler )
					.one( touchStopEvent, function() {
						$pg.off( touchMoveEvent, moveHandler );
						
						if ( start && stop ) {
							if ( stop.time - start.time < $.event.special.swipe.durationThreshold &&
								Math.abs( start.coords[ 0 ] - stop.coords[ 0 ] ) > $.event.special.swipe.horizontalDistanceThreshold &&
								Math.abs( start.coords[ 1 ] - stop.coords[ 1 ] ) < $.event.special.swipe.verticalDistanceThreshold ) {
								
								if( start.coords[0] > stop.coords[0] )
									that.outdent();    // 標號層級減一級, 例：(一)變成二、
								else
									that.indent();     // 標號層級加一級, 例：(二)變成１、
							}
						}
						start = stop = undefined;
					});
			})
			.on("click", function(event) {
				theLogger.log("'" + this.textContent + "'.on" + event.type);
				var c = $(this).closest(".viewPort").data("editCursor");
				setTimeout(function() {
					var cmds = [];
						cmds.push({name:"隱藏標號", func:that.toggleNumbering, target:that});
					cmds.push({name:"減少階層", func:that.outdent, target:that});
					cmds.push({name:"增加階層", func:that.indent, target:that});
					
					c.cmdFloat.setCmds(cmds);
					c.cmdFloat.setElem(that.$span.get(0), -1);
				}, 300);
				// 1131227 Raymond 1131303 隱藏錯別字校正子視窗
				that.para.getModel().hideEC();
				return false;
			});
		}
