	function Blinker($cursor) {
		
		this.$float = $cursor || $("<div class='Cursor'></div>");
		
		this.setPos = function(coord, visible) {
			if(visible)
				this.$float.css({left: coord.x, top: coord.y, display: "block"});
			else
				this.$float.css("display", "none");
		}
	}
