							theLogger.warn("輸入字元" + (tl-i-2) + "~" + (tl-i-1) + "為代理對(Surrogate pair)");
							rng2.setStart(rng.startContainer, rng.startOffset - 2);	// 原來rng的內容被切開後startOffset會跟著減, 所以不需要算入一開始的offset-字數
							sp = true;
