					var cnd, ofs = rng.startOffset;
					if(rng.startContainer.nodeType == 3) {
						cnd = rng.startContainer;
					}
					else if(rng.startContainer.nodeType == 1 && rng.startContainer.nodeName == "INS") {
						cnd = topMod.childNodes[0];
					}
