									if(prev.nodeValue.length > 1 && prev.nodeValue[prev.nodeValue.length-2].match(/[\uD800-\uDBFF]/) && prev.nodeValue[prev.nodeValue.length-1].match(/[\uDC00-\uDFFF]/)) {
										theLogger.warn("[DELE:151]前一元素是文字'" + prev.textContent + "'(" + prev.length + "), 刪除第" + (prev.length - 2) + "字'" + prev.nodeValue[prev.nodeValue.length-2] + prev.nodeValue[prev.nodeValue.length-1] + "'(Surrogate Pair)");
										rng2.setStart(prev, prev.nodeValue.length - 2);
									}
									else {
									theLogger.warn("前一元素是文字'" + prev.textContent + "'(" + prev.length + "), 刪除第" + (prev.length - 1) + "字");
									rng2.setStart(prev, prev.length - 1);
									}
									rng2.setEnd(prev, prev.length);
