									//var mod = $("<del style='color:" + clr + "' data-sn='" + sn + "' title='" + tipInfo + "'/>").get(0);
									var mod = $("<del style='color:" + clr + "' data-sn='" + sn + "' data-date='" + time + "' title='" + tipInfo + "'/>").get(0);
									rng2.surroundContents(mod);
