												//rng2.selectNodeContents(redElems[0]);
												var cn = redElems[0];
												while(cn.nodeType == 1 && cn.childNodes.length > 0)
													cn = cn.childNodes[0];
												rng2.selectNodeContents(cn);
												rng2.collapse(true);
