								var nxt = _getNextVisibleSibling(topMod);
								$(topMod).remove();
								if(!!prev)
									_setCursorRange(prev);
								else if(!!nxt)
									_setCursorRange(nxt, 0);
								else
									_setCursorRange(par, 0);
								skipSetCursorRange = true;	// 已設過游標位置, 忽略下面的_setCursorRange程序
