								//var mod = $("<del class='" + clsName + "' style='color:" + clr + "' data-sn='" + sn + "' data-date='" + time + "' title='" + tipInfo + "'>" + nxt.textContent + "</del>").get(0);
								var mod = $("<del class='" + clsName + "' style='color:" + clr + "' data-sn='" + sn + "' data-date='" + time + "' title='" + tipInfo + "'>" + o.node.textContent + "</del>").get(0);
								$(o.node).remove();
