	// 字體大小
	$("#btnSetFontSize").on("change", function(evt) {
		console.log("%cCTBL%c: 變更字體大小 -", clr1, clr0, this.value);
		if(_selectedTD.length && !!_selectedRange) {
			let $s = getSelectedElems(_selectedRange, "P");
			if($s.length) {
				$s.css("font-size", this.value);
				_updModTime("字體大小");
			}
		}
	});
